from biginteger import BigInt
from bigdecimal import BigDecimal
from decimal import Decimal
from scinot import SciNot
from expantanum import ExpantaNum
from powertower import PowerTower
from context import DEFAULT_CONTEXT, ArithmeticContext
import math

MAX_BIGINT_SCINOT_CONVERSION_DIGITS = 4000
SCINOT_CONVERSION_PRECISION = 30

from decimal import Decimal, localcontext
from scinot import SciNot


def integer_power_to_scinot(base, exponent, precision=28):
    """Approximate an integer power directly as SciNot, without building it."""
    if isinstance(base, bool) or not isinstance(base, int):
        raise TypeError("Base must be an integer.")
    if isinstance(exponent, bool) or not isinstance(exponent, int):
        raise TypeError("Exponent must be an integer.")
    if exponent < 0:
        raise ValueError("Exponent must be nonnegative.")
    if base == 0:
        return SciNot(0)
    if exponent == 0:
        return SciNot(1)

    negative = base < 0 and exponent % 2 == 1
    base = abs(base)

    if base == 1:
        return SciNot(-1 if negative else 1)

    with localcontext() as ctx:
        ctx.prec = precision + 10

        log_value = Decimal(base).log10() * exponent
        sci_exponent = int(log_value // 1)
        fractional_part = log_value - sci_exponent
        coefficient = Decimal(10) ** fractional_part

        if negative:
            coefficient = -coefficient

        ctx.prec = precision
        return SciNot(+coefficient, sci_exponent)

def to_bigdecimal(value):
    """Convert an integer or supported value to BigDecimal exactly."""
    if isinstance(value, BigDecimal):
        return value

    if isinstance(value, BigInt):
        value = str(value)
    elif isinstance(value, int):
        value = str(value)
    elif isinstance(value, float):
        raise TypeError(
            "Float conversion is disabled to avoid precision loss."
        )

    return BigDecimal.parse(str(value))

def _scinot_to_powertower(value):
    """Convert sufficiently large exact powers of ten to PowerTower."""
    if value.exponent <= MAX_BIGINT_SCINOT_CONVERSION_DIGITS:
        return None

    if value.coefficient != 1:
        return None

    return PowerTower(1, value.exponent)

def to_bigint_exact(value):
    """Convert to BigInt only when the value is an exact integer."""
    if isinstance(value, BigInt):
        return value

    if isinstance(value, int):
        return BigInt(value)

    decimal = to_bigdecimal(value)

    if decimal.sign == 0:
        return BigInt(0)

    if decimal.exponent >= 0:
        integer = decimal.coefficient * 10 ** decimal.exponent
    else:
        divisor = 10 ** (-decimal.exponent)

        if decimal.coefficient % divisor != 0:
            raise ValueError("Value is not an exact integer.")

        integer = decimal.coefficient // divisor

    return BigInt(decimal.sign * integer)

def _bigint_to_scinot(value):
    """Convert BigInt to SciNot, rounding to 30 significant digits."""
    integer = value.value if isinstance(value, BigInt) else int(value)

    if integer == 0:
        return SciNot(0)

    sign = -1 if integer < 0 else 1
    integer = abs(integer)

    # Convert to decimal text in chunks of nine digits.
    base = 1_000_000_000
    chunks = []

    while integer:
        integer, remainder = divmod(integer, base)
        chunks.append(remainder)

        # Avoid spending excessive time converting enormous integers.
        if len(chunks) * 9 > MAX_BIGINT_SCINOT_CONVERSION_DIGITS + 9:
            raise OverflowError("BigInt exceeds the SciNot conversion cap.")

    digits = str(chunks[-1]) + "".join(
        f"{chunk:09d}" for chunk in reversed(chunks[:-1])
    )

    if len(digits) > MAX_BIGINT_SCINOT_CONVERSION_DIGITS:
        raise OverflowError("BigInt exceeds the SciNot conversion cap.")

    precision = SCINOT_CONVERSION_PRECISION
    leading = digits[:precision]

    # Round half-up using the first discarded digit.
    if len(digits) > precision and digits[precision] >= "5":
        leading = str(int(leading) + 1)

    coefficient = Decimal(leading).scaleb(-(len(leading) - 1))
    return SciNot(sign * coefficient, len(digits) - 1)


def _prepare_pair(a, b):
    """Choose compatible representations for arithmetic operands."""

    if isinstance(a, float) or isinstance(b, float):
        raise TypeError("Float operands are not supported; use strings.")

    if isinstance(a, PowerTower) or isinstance(b, PowerTower):
        def convert(value):
            if isinstance(value, PowerTower):
                return value
            if isinstance(value, BigInt):
                return PowerTower(0, str(value))
            if isinstance(value, int) and not isinstance(value, bool):
                return PowerTower(0, str(value))
            if isinstance(value, str):
                return PowerTower(0, value)
            raise TypeError(
                f"Cannot mix PowerTower with {type(value).__name__}"
            )

        return convert(a), convert(b), "powertower"
    
    if isinstance(a, ExpantaNum) or isinstance(b, ExpantaNum):
        if isinstance(a, PowerTower) or isinstance(b, PowerTower):
            raise TypeError(
                "Mixing ExpantaNum and PowerTower is not supported yet."
            )

        def convert(value):
            if isinstance(value, ExpantaNum):
                return value
            if isinstance(value, (BigInt, BigDecimal)):
                return ExpantaNum(str(value))
            if isinstance(value, int) and not isinstance(value, bool):
                return ExpantaNum(value)
            if isinstance(value, str):
                return ExpantaNum(value)
            raise TypeError(
                f"Cannot mix ExpantaNum with {type(value).__name__}"
            )

        return convert(a), convert(b), "expantanum"

    if isinstance(a, SciNot) or isinstance(b, SciNot):
        if isinstance(a, BigDecimal) or isinstance(b, BigDecimal):
            raise TypeError(
                "Mixed SciNot and BigDecimal operations "
                "are not supported yet."
            )
    
        def convert(value):
            if isinstance(value, SciNot):
                tower = _scinot_to_powertower(value)
                return tower if tower is not None else value

            if isinstance(value, BigInt):
                return _bigint_to_scinot(value)

            return SciNot.parse(str(value))

        a_converted = convert(a)
        b_converted = convert(b)

        if isinstance(a_converted, PowerTower) or isinstance(
            b_converted, PowerTower
        ):
            return a_converted, b_converted, "powertower"

        return a_converted, b_converted, "scinot"
    
    if any(
        isinstance(value, str)
        and ("e" in value.lower() or "* 10^" in value)
        for value in (a, b)
    ):
        return SciNot.parse(str(a)), SciNot.parse(str(b)), "scinot"

    if isinstance(a, BigDecimal) or isinstance(b, BigDecimal):
        return to_bigdecimal(a), to_bigdecimal(b), "bigdecimal"

    if any(
        isinstance(value, str) and "." in value
        for value in (a, b)
    ):
        return to_bigdecimal(a), to_bigdecimal(b), "bigdecimal"

    return BigInt(a), BigInt(b), "bigint"

def add(a, b):
    a, b, kind = _prepare_pair(a, b)
    if kind == ExpantaNum:
        return a
    return a + b


def subtract(a, b):
    a, b, kind = _prepare_pair(a, b)
    if kind == ExpantaNum:
        return a
    return a - b


def multiply(a, b):
    a, b, kind = _prepare_pair(a, b)
    if kind == ExpantaNum:
        return a

    if kind == "scinot":
        return a * b

    return a * b


def divide(a, b, context=None):
    if context is None:
        context = DEFAULT_CONTEXT

    if not isinstance(context, ArithmeticContext):
        raise TypeError("context must be an ArithmeticContext")

    a, b, kind = _prepare_pair(a, b)

    if isinstance(a,BigInt):
        a = BigDecimal.parse(str(a))
    if isinstance(a,BigInt):
        b = BigDecimal.parse(str(b))

    if kind == "powertower":
        return a / b
    elif kind == "bigdecimal":
        return a.__truediv__(
            b,
            precision=context.precision,
            rounding=context.rounding,
        )
    elif kind == "scinot":
        return a / b
    elif kind == "bigint":
        if b == 0:
            raise ZeroDivisionError("Cannot divide by zero.")
        return a / b
    elif kind == "expantanum":
        return a

    raise TypeError(f"Unsupported division type: {kind}")


def integer_divide(a, b):
    a = to_bigint_exact(a)
    b = to_bigint_exact(b)

    if b.value == 0:
        raise ZeroDivisionError("Cannot divide by zero")

    quotient = abs(a.value) // abs(b.value)

    if (a.value < 0) != (b.value < 0):
        quotient = -quotient

    return BigInt(quotient)


def remainder(a, b):
    a = to_bigint_exact(a)
    b = to_bigint_exact(b)

    if b.value == 0:
        raise ZeroDivisionError("Cannot divide by zero")

    quotient = integer_divide(a, b).value
    return BigInt(a.value - quotient * b.value)

def power(a, b):
    a,b,kind = _prepare_pair(a,b)
    if isinstance(a,BigDecimal) or isinstance(b,BigDecimal):
        if isinstance(a,BigDecimal) and not isinstance(b,BigDecimal):
            b = BigDecimal.parse(str(b))
        if isinstance(b,BigDecimal) and not isinstance(a,BigDecimal):
            a = BigDecimal.parse(str(a))
    else:
        a = to_bigint_exact(a)
        b = to_bigint_exact(b)
            # Extract the underlying Python integers from BigInt.
        base = a.value
        exponent = b.value

        if (
            exponent >= 0
            and abs(base) > 1
            and exponent * abs(base).bit_length()
                > MAX_BIGINT_SCINOT_CONVERSION_DIGITS * 3.322
        ):
            return integer_power_to_scinot(base, exponent)
        
    return a**b

def arrow(a, b, c):
    return ExpantaNum.arrow(a,b,c)

def negate(a):
    return a * -1

def log10(a):
    if isinstance(a,BigInt):
        a = BigDecimal.parse(str(a))
    if isinstance(a, BigDecimal) or isinstance(a, SciNot):
        return a.log10()

def sqrt(a):
    if isinstance(a,BigInt):
        a = BigDecimal.parse(str(a))
    if isinstance(a, BigDecimal) or isinstance(a, SciNot):
        return a.sqrt()

def ackermann1(a):
    return ExpantaNum.arrow(a,a,a)

def ackermann2(a,b):
    temp = ExpantaNum.arrow(2,a-2,b+3)
    if a == 0:
        return b+1
    else:
        try:
            return int(temp.to_float())-3
        except OverflowError:
            return temp

def ackermann_dispatch(*args):
    if len(args) == 1:
        return ackermann1(args[0])
    if len(args) == 2:
        return ackermann2(args[0],args[1])

    raise ValueError("ackermann() expects at most two arguments: "+str(len(args))+" were given.")
def logb(a,b):
    if isinstance(a,BigInt):
        a = BigDecimal.parse(str(a))
    if isinstance(b,BigInt):
        b = BigDecimal.parse(str(b))
    if isinstance(a, BigDecimal) or isinstance(a, SciNot):
        return a.log10()/b.log10()

def expansion(a,b):
    return ExpantaNum(
        sign = 1,
        array = arrow(a,a,a).array,
        layer = int(str(b-2)),
    )

def factorial(a,b):
    factorialsby20 = ['1', '51090942171709440000', '33452526613163807108170062053440751665152000000000', '507580213877224798800856812176625227226004528988036003099405939480985600000000000000', '5797126020747367985879734231578109105412357244731625958745865049716390179693892056256184534249745940480000000000000000000', '9425947759838359420851623124482936749562312794702543768327889353416977599316221476503087861591808346911623490003549599583369706302603264000000000000000000000000', '809429852527344373968162284544935082997082306309701607045776233628497660426640521713391773997910182738287074185078904956856663439318382745047716214841147650721760223072092160000000000000000000000000000', '1898143759076170969428526414110767793728175011895349373797246196996101911759765533248506853474785138972002542682916216702019230820297304827075914771733278062452780211579860725280286887880928321116599494314557440000000000000000000000000000000000', '75907050539472187290751785709367294850142012310319093001281637109124354328254874435863462868336514307629599224875954998199218529677928181579808491945059049643495805791487187086484320607292781408814365272803092482649411787748723446459202305005715456000000000000000000000000000000000000000', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '']
    if isinstance(a,BigInt) or isinstance(a,SciNot):
        a = BigInt(str(a))
    if a < BigInt("1000"):
        #use the pre-computed dictionary of the first 980 factorials by 20s to speed up computation
        temp = BigInt(factorialsby20[int(str(integer_divide(a,20)))])
        for i in range(int(str(integer_divide(a,20)))*20,int(str(a))):
            temp *= BigInt(str(i))+BigInt("1")
        return BigInt(str(temp))
    elif a < BigInt("1500"):
        #after that, start with 980! and go from there.
        temp = BigInt(factorialsby20[49])
        for i in range(a-980):
            temp *= BigInt(str(i))+BigInt("1")
        return BigInt(str(temp))
    else:
        #Sterling approximation after n = 1'500 (THIS IS PRETTY INACCURATE)
        a = BigDecimal.parse(str(a))
        exp = a*log10(a)-(BigDecimal.parse("0.434294481903251")*a)+(BigDecimal.parse("0.5")*log10(BigDecimal.parse("2")*(BigDecimal.parse("3.141592653589793")*a)))
        return SciNot(BigDecimal.parse("10")**(exp-BigDecimal.floor_decimal(exp)),BigDecimal.floor(exp))